package hexadecimal

import (
	"errors"
	"fmt"
)

// Sentinel errors returned by ParseHex.
var (
	ErrSyntax = errors.New("syntax error")
	ErrRange  = errors.New("range error")
)

// maxInt64 is the largest value an int64 can hold.
const maxInt64 = 1<<63 - 1

// ParseHex converts a hexadecimal string (e.g. "10af8c") to its decimal
// equivalent using first principles, without any conversion library.
//
// It returns an error wrapping ErrSyntax if the input is empty or contains
// a character that is not a hexadecimal digit, and an error wrapping
// ErrRange if the value does not fit in an int64.
func ParseHex(in string) (int64, error) {
	if in == "" {
		return 0, fmt.Errorf("%w: input is empty", ErrSyntax)
	}

	var out int64
	for _, r := range in {
		var digit int64
		switch {
		case r >= '0' && r <= '9':
			digit = int64(r - '0')
		case r >= 'a' && r <= 'f':
			digit = int64(r-'a') + 10
		case r >= 'A' && r <= 'F':
			digit = int64(r-'A') + 10
		default:
			return 0, fmt.Errorf("%w: %q is not a hexadecimal digit", ErrSyntax, r)
		}

		// Overflow check: out*16 + digit must not exceed maxInt64.
		if out > (maxInt64-digit)/16 {
			return 0, fmt.Errorf("%w: %q does not fit in an int64", ErrRange, in)
		}
		out = out*16 + digit
	}
	return out, nil
}

// HandleErrors calls ParseHex on each input and returns a matching list of
// "none", "syntax", or "range" describing the error case for each.
func HandleErrors(in []string) []string {
	out := make([]string, len(in))
	for i, s := range in {
		_, err := ParseHex(s)
		switch {
		case err == nil:
			out[i] = "none"
		case errors.Is(err, ErrRange):
			out[i] = "range"
		default:
			out[i] = "syntax"
		}
	}
	return out
}
